import re
events=[]
class Message:
 def __str__(self):
  events.append('str')
  return 'bad'
class Pattern:
 def count(self,newline,start,end):
  events.append(('count',newline,start,end))
  return 2
 def rfind(self,newline,start,end):
  events.append(('rfind',newline,start,end))
  return 4
 def __contains__(self,newline):
  events.append(('contains',newline))
  return True
pattern=Pattern()
e=re.error(Message(),pattern,7)
print(str(e),e.pattern is pattern,e.lineno,e.colno)
print(events)

